INSERT INTO legal_provision (provision_id, statute_id, provision_reference, provision_heading, provision_text) VALUES(1, 1, 'Order XXXIX Rules 1-2', 'Temporary injunctions', 'Power to grant temporary injunctions in the circumstances set out in the Code.'),
(2, 1, 'Section 9', 'Courts to try all civil suits unless barred', 'Civil courts have jurisdiction to try suits of a civil nature unless cognizance is expressly or impliedly barred.'),
(3, 1, 'Section 47', 'Questions to be determined by executing court', 'Questions relating to execution, discharge or satisfaction of a decree are determined by the executing court.'),
(4, 2, 'Section 303', 'Theft', 'Provision concerning dishonest taking of movable property.'),
(5, 3, 'Section 480', 'When bail may be taken in non-bailable offences', 'Provision governing grant of bail in non-bailable offences, subject to statutory conditions.'),
(6, 4, 'Section 10', 'Specific performance in respect of contracts', 'Specific performance may be enforced subject to the provisions of the Act.'),
(7, 5, 'Section 13', 'Divorce', 'Grounds on which a marriage may be dissolved by a decree of divorce.'),
(8, 6, 'Section 12A', 'Pre-institution mediation and settlement', 'Pre-institution mediation applies where urgent interim relief is not contemplated.'),
(9, 7, 'Article 226', 'Power of High Courts to issue certain writs', 'High Courts may issue writs, directions or orders for the purposes stated in the Constitution.'),
(10, 1, 'Order VII Rule 1', 'Particulars to be contained in plaint', 'Prescribes particulars to be contained in a plaint.');
