-- ============================================================================
-- CCMS V5 | Realistic, relational seed dataset
-- Run this file AFTER CCMS_V5_schema.sql in the same empty database.
-- The schema's lookup rows (case types, statuses, roles, etc.) are inserted by
-- the schema script and are referenced here.
-- All names and case narratives below are fictional. Email domains use the
-- reserved .test namespace. Phone strings are masked and cannot be dialled.
-- Seed login password for every account: CourtAccess@2026
-- Password hashes are Argon2id; replace or re-hash them for your own auth setup.
-- ============================================================================

BEGIN;































UPDATE case_registration SET is_current = FALSE WHERE case_id = 9 AND is_current = TRUE;




































